// Lee el payload real de Meta y decide si el evento es procesable.
const body  = $json.body || {};
const value = body.entry?.[0]?.changes?.[0]?.value || {};
const msg   = value.messages?.[0];

if (!msg) return [{ json: { procesable: false, motivo: 'payload_sin_mensaje (status u otro evento)' } }];

const wamid    = msg.id || '';
const telefono = String(msg.from || '').replace(/\D/g, '');
const tipo     = msg.type || 'desconocido';

let mensaje = '', procesable = true, motivo = '';
let canal = 'whatsapp_directo', propiedad_origen = '', tipo_propiedad = '', operacion_origen = '';
let es_audio = false, media_id = '';

if (tipo === 'text') {
  mensaje = (msg.text?.body || '').trim();
  if (!mensaje) { procesable = false; motivo = 'texto_vacio'; }

  // Las publicaciones viven en DOS dominios y hay que reconocer los dos:
  //   departamento.mercadolibre.cl/MLC-4112483036-arriendo-amoblado-...   (lo que llega por WhatsApp)
  //   www.portalinmobiliario.com/MLC-1975411451-santa-maria-de-manquehue-... (panel de Alice)
  const esPortal = /(?:mercadolibre|portalinmobiliario)\.(?:cl|com)/i.test(mensaje);
  const mId = mensaje.match(/\bMLC-?\s?(\d{6,})\b/i);
  if (mId) {
    propiedad_origen = 'MLC-' + mId[1];
    if (esPortal) canal = 'portal_inmobiliario';
  }
  // Codigo interno, por si alguna vez se usa una nomenclatura propia
  const mCodigo = mensaje.match(/\bPH-?\s?(\d{3,5})\b/i);
  if (mCodigo && !mId) propiedad_origen = 'PH-' + mCodigo[1];
  if (/instagram|ig\.me/i.test(mensaje)) canal = 'instagram';

  if (/\bcasa\.mercadolibre/i.test(mensaje))                      tipo_propiedad = 'casa';
  else if (/\bdepartamento\.mercadolibre/i.test(mensaje))          tipo_propiedad = 'departamento';
  else if (/\b(?:parcela|terreno|sitio)\.mercadolibre/i.test(mensaje)) tipo_propiedad = 'parcela';

  const slug = (mensaje.match(/MLC-?\d+-([a-z0-9-]+)/i) || [])[1] || '';
  if (/arriend/i.test(slug)) operacion_origen = 'arriendo';
  else if (/vent|vende/i.test(slug)) operacion_origen = 'venta';

} else if (tipo === 'audio') {
  // NOVEDAD v2: las notas de voz se transcriben, no se rebotan.
  es_audio = true;
  media_id = msg.audio?.id || '';
  mensaje  = '';
  motivo   = 'audio_a_transcribir';
  if (!media_id) { procesable = false; motivo = 'audio_sin_media_id'; }

} else if (['image','document'].includes(tipo)) {
  mensaje = '[Instruccion del sistema: el contacto envio un archivo de tipo "' + tipo + '". ' +
            'Agradecelo, confirma que quedo recibido y dile que Alice lo revisa. ' +
            'Si estaba pendiente documentacion de arriendo, marca documentacion como "parcial" ' +
            'salvo que diga explicitamente que envio todo.]';
  motivo = 'archivo_' + tipo;

} else if (['video','sticker','location','contacts'].includes(tipo)) {
  mensaje = '[Instruccion del sistema: el contacto envio un mensaje de tipo "' + tipo + '" que no puedes ver. ' +
            'Pidele amablemente que lo escriba.]';
  motivo = 'multimedia_' + tipo;

} else { procesable = false; motivo = 'tipo_no_soportado: ' + tipo; }

if (!wamid || !telefono) { procesable = false; motivo = 'faltan_wamid_o_telefono'; }

return [{ json: {
  procesable, motivo, wamid, telefono, tipo, mensaje, canal,
  propiedad_origen, tipo_propiedad, operacion_origen,
  es_audio, media_id,
  numero_bot: value.metadata?.phone_number_id || '',
  timestamp: $now.toISO()
} }];

// Une las dos entradas: texto normal, o nota de voz ya transcrita.
// Desde aca en adelante TODO el workflow lee el mensaje desde este nodo.
const base = $('Validar y Extraer Mensaje').first().json;
const inp  = $input.first()?.json || {};

let mensaje = base.mensaje;
let transcrito = false;

if (base.es_audio) {
  const texto = String(inp.text || '').trim();
  if (texto) {
    mensaje = texto;
    transcrito = true;
  } else {
    // Whisper fallo: no dejamos al contacto sin respuesta
    mensaje = '[Instruccion del sistema: el contacto envio una nota de voz que no se pudo transcribir. ' +
              'Pidele con amabilidad que te lo escriba, sin dar detalles tecnicos.]';
  }
}

return [{ json: { ...base, mensaje, transcrito } }];

// El modelo propone; el codigo decide.
// Aca se validan agendamiento, ruteo por valor y se CALCULA la tasacion.
const raw     = $input.first().json;
const msgData = $('Mensaje · Texto final').first().json;
const cfg     = $('⚙️ CONFIG · Cliente').first().json;
const prev    = $('Contexto · Preparar').first().json.estado_previo || {};
const prep    = $('Contexto · Preparar').first().json;

let r = null, errorParseo = '';
try {
  const t = raw.choices?.[0]?.message?.content ?? '';
  r = JSON.parse(t.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/, '').trim());
} catch (e) { errorParseo = e.message; }

if (!r || typeof r !== 'object' || typeof r.respuesta !== 'string') {
  r = { respuesta: 'Perdona, se me trabo el sistema un segundo. ¿Me repites eso?',
        nuevo_estado: prev.estado_conversacion || 'INICIO', intencion: 'otro', lead: {},
        propiedad_interes: '', enviar_ficha: false, tasacion_lista: false, tasacion: {},
        agendar: false, agendamiento: {}, accion_interna: 'ninguna',
        nota_interna: 'ERROR parseo respuesta IA: ' + (errorParseo || 'estructura invalida') };
}

const num = (v) => Number(String(v ?? '').replace(/[^0-9.]/g, '')) || 0;
const txt = (v) => String(v ?? '').trim();
const norm = (v) => txt(v).toLowerCase();

// ── Lead (conserva lo previo si el modelo lo dejo vacio) ──
const pl = prep.lead_previo || {}, L = r.lead || {};
const lead = {
  nombre:          txt(L.nombre)           || pl.nombre          || '',
  operacion:       norm(L.operacion)       || pl.operacion       || '',
  comuna:          txt(L.comuna)           || pl.comuna          || '',
  dormitorios:     txt(L.dormitorios)      || pl.dormitorios     || '',
  presupuesto_uf:  num(L.presupuesto_uf)   || pl.presupuesto_uf  || 0,
  presupuesto_clp: num(L.presupuesto_clp)  || pl.presupuesto_clp || 0,
  financiamiento:  norm(L.financiamiento)  || pl.financiamiento  || '',
  documentacion:   norm(L.documentacion)   || pl.documentacion   || ''
};

// ── La propiedad debe existir en el stock que le mostramos al modelo ──
let propiedadInteres = txt(r.propiedad_interes);
if (propiedadInteres && !(prep.stock_visible || []).includes(propiedadInteres)) {
  r.nota_interna = ((r.nota_interna || '') + ' | Propiedad inventada, descartada: ' + propiedadInteres).trim();
  propiedadInteres = '';
}

// ── SCORE ──
let score = 0;
if (lead.nombre) score += 10;
if (lead.operacion) score += 10;
if (lead.comuna) score += 10;
if (lead.dormitorios) score += 5;
if (lead.presupuesto_uf || lead.presupuesto_clp) score += 15;
if (lead.financiamiento === 'contado') score += 30;
else if (lead.financiamiento === 'preaprobado') score += 25;
else if (lead.financiamiento === 'por evaluar') score += 8;
if (lead.documentacion === 'completa') score += 20;
else if (lead.documentacion === 'parcial') score += 8;
if (propiedadInteres) score += 10;
score = Math.min(100, score);

// ── RUTEO POR VALOR ──
const umbralUF  = num(cfg.umbral_uf_alto)  || 12000;
const umbralCLP = num(cfg.umbral_clp_alto) || 2500000;
const prioritarias = String(cfg.comunas_prioritarias || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const intencion = ['busqueda','reserva','captacion','postventa','otro'].includes(r.intencion) ? r.intencion : 'otro';
const cl = lead.comuna.toLowerCase();
const esPrioritaria = cl.length > 2 && prioritarias.some(c => cl.includes(c) || c.includes(cl));

let nivel = 'estandar';
if (lead.presupuesto_uf >= umbralUF || lead.presupuesto_clp >= umbralCLP) nivel = 'alto';
else if (intencion === 'captacion' && esPrioritaria) nivel = 'alto';
else if (lead.presupuesto_uf >= 4000 || lead.presupuesto_clp >= 700000) nivel = 'medio';

let accion = ['ninguna','escalar_humano','alto_valor'].includes(r.accion_interna) ? r.accion_interna : 'ninguna';
if (nivel === 'alto' && accion === 'ninguna') accion = 'alto_valor';
if (intencion === 'postventa') accion = 'escalar_humano';
const slaMinutos = nivel === 'alto' ? 60 : (nivel === 'medio' ? 240 : 1440);

// ══ TASACION EXPRESS — el rango lo calcula el codigo, nunca el modelo ══
const T = r.tasacion || {};
let tasacionLista = r.tasacion_lista === true;
const tCom = txt(T.comuna) || lead.comuna;
const tTipo = norm(T.tipo);
const tM2 = num(T.m2);
let tasacion = null;

if (tasacionLista) {
  const refs = (prep.referencias || []).filter(x => x && x.comuna);
  const match = refs.find(x => norm(x.comuna) === norm(tCom) && norm(x.tipo) === tTipo)
             || refs.find(x => norm(x.comuna) === norm(tCom));

  if (!match || tM2 < 20 || tM2 > 2000) {
    tasacionLista = false;
    r.nota_interna = ((r.nota_interna || '') +
      ' | Tasacion bloqueada: ' + (!match ? 'sin valor de referencia para ' + tCom : 'm2 fuera de rango (' + tM2 + ')')).trim();
    r.respuesta = !match
      ? 'Para esa comuna prefiero que el numero te lo de Alice directamente, que es tasadora. ¿Te acomoda que se junten esta semana?'
      : 'Necesito confirmar los metros cuadrados construidos para calcularlo bien. ¿Cuantos son?';
    r.nuevo_estado = 'CAPTACION';
  } else {
    const ufMin = num(match.uf_m2_min), ufMax = num(match.uf_m2_max);
    const ufProm = (ufMin + ufMax) / 2;
    const red = (x) => Math.round(x / 50) * 50;
    const rapido = red(tM2 * ufProm * 0.93);   // vender en 3 meses
    const paciente = red(tM2 * ufProm * 1.08); // esperar hasta un ano

    tasacion = { comuna: tCom, tipo: tTipo || 'propiedad', m2: tM2,
                 uf_m2_min: ufMin, uf_m2_max: ufMax,
                 rango_rapido: rapido, rango_paciente: paciente,
                 fuente: match.fuente || 'referencia interna',
                 actualizado: match.actualizado || '' };

    const fmt = (n) => n.toLocaleString('es-CL');
    const etq = tTipo === 'casa' ? 'Casa' : (tTipo === 'parcela' ? 'Parcela' : 'Departamento');

    // El rango se calcula, pero NO se le entrega al cliente.
    // Alice, 11-ago: "podria estar no considerando factores importantes del
    // precio, que bajen la emocion de un cliente al querer vender su propiedad
    // conmigo... dejaria la evaluacion de precio hasta que me contacte con el".
    // El numero viaja solo al correo interno para que ella llegue preparada.
    const yaConfirmado = (prep.historial_con_cliente || [])
      .some(m => m.rol === 'bot' && /evalua el precio y te env/i.test(String(m.texto || '')));
    if (!yaConfirmado) {
      r.respuesta =
        'Perfecto, con esto Alice ya puede trabajar.\n\n' +
        'Ella evalua el precio y te envia el analisis por correo. Es tasadora ' +
        'certificada, asi que pondera terminaciones, orientacion, piso y gastos ' +
        'comunes, no solo los metros.\n\n' +
        '¿Te acomoda que se junten esta semana? Puede ser en la propiedad, en su ' +
        'oficina o por videollamada.';
    }
    r.nuevo_estado = 'TASACION';
  }
}

// ── VALIDACION DEL AGENDAMIENTO ──
const AG = r.agendamiento || {};
let agendar = r.agendar === true;
let tipoAg = ['visita','tasacion','llamada'].includes(txt(AG.tipo)) ? txt(AG.tipo) : 'visita';
let fecha = txt(AG.fecha), hora = txt(AG.hora);
let modalidad = ['propiedad','oficina','videollamada'].includes(txt(AG.modalidad)) ? txt(AG.modalidad) : 'propiedad';
let motivo = '';

if (agendar && !tasacionLista) {
  const reF = /^\d{4}-\d{2}-\d{2}$/, reH = /^([01]?\d|2[0-3]):[0-5]\d$/;
  if (!lead.nombre) motivo = 'me falta tu nombre';
  else if (!reF.test(fecha)) motivo = 'me falta el dia';
  else if (!reH.test(hora))  motivo = 'me falta la hora';
  else {
    const [hh, mm] = hora.split(':').map(Number);
    const minutos = hh * 60 + mm;
    const ahora = $now.hour * 60 + $now.minute;
    const hoy = $now.toFormat('yyyy-MM-dd');
    const dow = new Date(fecha + 'T12:00:00Z').getUTCDay();
    if (fecha < hoy) motivo = 'esa fecha ya paso';
    else if (fecha === hoy && minutos <= ahora + 60) motivo = 'necesito al menos una hora de anticipacion';
    else if (dow === 0) motivo = 'los domingos Alice no hace visitas';
    else if (minutos < 540 || minutos > 1200) motivo = 'las visitas son entre 09:00 y 20:00';
    else if (tipoAg === 'visita' && lead.operacion === 'arriendo' &&
             !['completa','parcial'].includes(lead.documentacion))
      motivo = 'para coordinar la visita necesito primero tus liquidaciones, cotizaciones AFP y DICOM';
    else if (tipoAg === 'visita' && !propiedadInteres) motivo = 'me falta confirmar cual propiedad quieres ver';
  }
  if (motivo) {
    agendar = false;
    r.respuesta = 'Casi listo. Solo un detalle: ' + motivo + '. ¿Me lo confirmas?';
    r.nuevo_estado = motivo.indexOf('DICOM') >= 0 ? 'DOCUMENTOS' : 'AGENDANDO';
    if (/fecha|dia|hora|domingo|09:00|anticipacion/.test(motivo)) { fecha = ''; hora = ''; }
    r.nota_interna = ((r.nota_interna || '') + ' | Agendamiento bloqueado: ' + motivo).trim();
  }
} else if (agendar && tasacionLista) {
  agendar = false; // la tasacion ya ocupa este turno; el agendamiento va en el siguiente
}

// ── Ficha: SIEMPRE se manda algo. Con foto va como imagen, sin foto como
// texto con el link del Portal (donde si hay fotos). Antes, si la propiedad
// no tenia foto, el bot prometia la ficha y no llegaba nada.
// El modelo propone, el codigo decide — y aca decide que NO.
// El LLM dejaba enviar_ficha = true para siempre, asi que la ficha se pegaba a
// cada respuesta. Ahora manda la deteccion del codigo, no su booleano.
if (!propiedadInteres && prep.pide_ficha && prep.ultima_propiedad) {
  propiedadInteres = String(prep.ultima_propiedad);
}
const yaSeMando = (prep.fichas_ya_enviadas || []).includes(String(propiedadInteres));
let enviarFicha = prep.pide_ficha === true && !!propiedadInteres &&
                  !tasacionLista && !yaSeMando;
if (r.enviar_ficha === true && !prep.pide_ficha) {
  r.nota_interna = ((r.nota_interna || '') +
    ' | El modelo quiso mandar ficha sin que la pidieran, bloqueada').trim();
}
if (yaSeMando) {
  r.nota_interna = ((r.nota_interna || '') +
    ' | Ficha de ' + propiedadInteres + ' ya enviada antes, no se repite').trim();
}
let fichaConFoto = false;
let ficha = null;

if (enviarFicha) {
  const p = (prep.stock_completo || []).find(x => String(x.id) === propiedadInteres);
  if (!p) {
    enviarFicha = false;               // el modelo se invento el ID
  } else {
    const foto = txt(p.foto);
    const precio = norm(p.operacion) === 'venta'
      ? 'UF ' + num(p.uf).toLocaleString('es-CL')
      : (num(p.clp) ? '$' + num(p.clp).toLocaleString('es-CL') + ' / mes'
                    : 'UF ' + num(p.uf).toLocaleString('es-CL') + ' / mes');

    // Solo se imprime lo que existe. Nada de "0D / 0B · 0 m2".
    const specs = [];
    if (num(p.dormitorios)) specs.push(num(p.dormitorios) + 'D');
    if (num(p.banos))       specs.push(num(p.banos) + 'B');
    if (num(p.m2))          specs.push(num(p.m2) + ' m²');

    const lineas = [
      '*' + txt(p.titulo || p.descripcion || p.id) + '*',
      precio,
      [txt(p.tipo), txt(p.comuna), specs.join(' / ')].filter(Boolean).join(' · '),
      txt(p.direccion) ? '📍 ' + txt(p.direccion) : '',
      txt(p.link) ? '\n' + txt(p.link) : ''
    ].filter(Boolean);

    const cuerpo = lineas.join('\n');
    fichaConFoto = /^https?:\/\//i.test(foto);
    ficha = {
      foto: fichaConFoto ? foto : '',
      caption: cuerpo,
      texto: cuerpo + (fichaConFoto ? '' : '\n\nEn el link estan todas las fotos.')
    };
  }
}

// ── ANTI-REPETICION (Alice, 11-ago: "me envio 3 veces el mismo rango, sin
// pedirlo" / "siento repite mucho el mensaje final, al menos 3 veces") ──
// Si lo que vamos a mandar es casi igual a algo que el bot ya dijo, se cambia
// por un seguimiento corto en vez de repetir el bloque entero.
(function evitarRepetir() {
  const previos = (prep.historial_con_cliente || [])
    .filter(m => m.rol === 'bot').slice(-4).map(m => String(m.texto || ''));
  if (!previos.length) return;

  const huella = (s) => String(s || '').toLowerCase()
    .replace(/[^a-z0-9áéíóúñ ]/gi, ' ').replace(/\s+/g, ' ').trim();
  const salida = huella(r.respuesta);
  if (salida.length < 40) return;

  const parecido = (a, b) => {
    const A = new Set(a.split(' ')), B = new Set(b.split(' '));
    if (!A.size || !B.size) return 0;
    let comunes = 0;
    A.forEach(w => { if (B.has(w)) comunes++; });
    return comunes / Math.max(A.size, B.size);
  };

  const repetido = previos.some(p => parecido(salida, huella(p)) > 0.78);
  if (!repetido) return;

  r.nota_interna = ((r.nota_interna || '') + ' | Respuesta repetida, reemplazada').trim();
  r.respuesta = lead.nombre
    ? 'Quedo atenta entonces, ' + lead.nombre + '. Cualquier duda me dices.'
    : 'Quedo atenta. Cualquier duda me dices.';
  enviarFicha = false;
})();

// ── Historial ──
const historial = prep.historial_con_cliente || [];
historial.push({ rol: 'bot', texto: r.respuesta, ts: new Date().toISOString() });
// Deja constancia de la ficha enviada: es lo que impide repetirla.
if (enviarFicha && propiedadInteres) {
  historial.push({ rol: 'bot', texto: '[ficha:' + propiedadInteres + ']',
                   ts: new Date().toISOString() });
}

const estados = ['INICIO','CALIFICANDO','MOSTRANDO_STOCK','DOCUMENTOS','AGENDANDO','AGENDADO',
                 'CONSULTA_RESERVA','CAPTACION','TASACION','SEGUIMIENTO','ESCALADO'];
const nuevoEstado = estados.includes(r.nuevo_estado) ? r.nuevo_estado
                    : (agendar ? 'AGENDADO' : (prev.estado_conversacion || 'CALIFICANDO'));

return [{ json: {
  respuesta: r.respuesta, nuevo_estado: nuevoEstado, intencion, lead, score, nivel,
  sla_minutos: slaMinutos, propiedad_interes: propiedadInteres,
  enviar_ficha: enviarFicha, ficha_con_foto: fichaConFoto, ficha,
  tasacion_lista: tasacionLista, tasacion,
  agendar, agendamiento: { tipo: tipoAg, fecha, hora, modalidad },
  accion_interna: accion, nota_interna: r.nota_interna || '',
  telefono: msgData.telefono, wamid: msgData.wamid, canal: msgData.canal,
  transcrito: !!msgData.transcrito, mensaje_cliente: msgData.mensaje,
  historial_para_sheets: JSON.stringify(historial.length > 40 ? historial.slice(-40) : historial)
} }];

// Codigo de agendamiento y fechas ISO con offset real de Chile.
const r = $('IA · Parsear y validar').first().json;
const cfg = $('⚙️ CONFIG · Cliente').first().json;
const fecha = r.agendamiento.fecha, hora = r.agendamiento.hora.padStart(5, '0');

function offsetSantiago(d) {
  const parts = new Intl.DateTimeFormat('en-US', { timeZone: 'America/Santiago', timeZoneName: 'longOffset' }).formatToParts(d);
  const tz = (parts.find(p => p.type === 'timeZoneName') || {}).value || '';
  const m = tz.match(/GMT([+-]\d{2}:\d{2})/);
  return m ? m[1] : '-04:00';
}
const off = offsetSantiago(new Date(fecha + 'T12:00:00Z'));
const [hh, mm] = hora.split(':').map(Number);
const dur = r.agendamiento.tipo === 'llamada' ? 30 : 60;
const fin = hh * 60 + mm + dur;
const endHora = String(Math.min(Math.floor(fin / 60), 23)).padStart(2, '0') + ':' + String(fin % 60).padStart(2, '0');

const sufijo = (r.wamid || '').replace(/[^A-Za-z0-9]/g, '').slice(-6).toUpperCase() || String(Date.now()).slice(-6);
const prefijo = r.agendamiento.tipo === 'tasacion' ? 'TAS' : (r.agendamiento.tipo === 'llamada' ? 'CAL' : 'VIS');

const stock = $('Contexto · Preparar').first().json.stock_completo || [];
const prop = stock.find(p => String(p.id) === r.propiedad_interes) || {};
const propTxt = r.propiedad_interes
  ? (r.propiedad_interes + ' · ' + (prop.tipo || '') + ' ' + (prop.comuna || '')).trim()
  : 'Por definir';
const lugar = r.agendamiento.modalidad === 'oficina' ? cfg.direccion_oficina
            : r.agendamiento.modalidad === 'videollamada' ? 'Videollamada'
            : (prop.direccion || propTxt);

return [{ json: { ...r,
  codigo_agenda: prefijo + '-' + fecha.replace(/-/g, '') + '-' + sufijo,
  start_iso: fecha + 'T' + hora + ':00' + off,
  end_iso:   fecha + 'T' + endHora + ':00' + off,
  propiedad_txt: propTxt, lugar,
  etiqueta_tipo: { visita: 'Visita', tasacion: 'Tasacion', llamada: 'Llamada' }[r.agendamiento.tipo] || 'Visita',
  icono_nivel: r.nivel === 'alto' ? '🔴' : (r.nivel === 'medio' ? '🟡' : '🟢')
} }];

// OpenAI fallo (timeout, 4xx/5xx, red). Respuesta segura al contacto.
const msgData = $('Mensaje · Texto final').first().json;
const err = $input.first().json;
return [{ json: {
  telefono: msgData.telefono, wamid: msgData.wamid,
  respuesta: 'Se me cayo el sistema un momento. Dame un par de minutos y me escribes de nuevo — o si prefieres, Alice te llama.',
  workflow: 'prohausen-agente-whatsapp-v3', nodo: 'IA · OpenAI Chat', tipo_error: 'openai_error',
  mensaje_error: String(err?.error?.message || err?.message || JSON.stringify(err || {})).slice(0, 300),
  fecha: $now.toISO()
} }];

// Arma el mensaje matinal de Alice: llamados prioritarios + publicaciones por vencer.
const leads = $('Brief · Leer leads').all().map(i => i.json).filter(l => l && l.telefono);
const props = $('Brief · Leer publicaciones').all().map(i => i.json).filter(p => p && p.id);
const num = (v) => Number(String(v ?? '').replace(/[^0-9.]/g, '')) || 0;
const ahora = new Date();
const horas = (iso) => {
  const t = Date.parse(iso || '');
  return isNaN(t) ? 999 : (ahora - t) / 3600000;
};

const recientes = leads.filter(l => horas(l.ultima_actualizacion) <= 48);
const cerrado = (l) => ['AGENDADO','CERRADO'].includes(String(l.estado).toUpperCase());
const agendados = recientes.filter(cerrado);

// Cada lead aparece UNA sola vez, en el bloque de mayor prioridad.
const usados = new Set();
const tomar = (fn) => recientes.filter(l => {
  if (usados.has(l.telefono) || cerrado(l)) return false;
  if (!fn(l)) return false;
  usados.add(l.telefono); return true;
});

// Orden de prioridad: captacion (inventario) > SLA vencido > alto valor
const captaciones = tomar(l => String(l.intencion).toLowerCase() === 'captacion');
const vencidos    = tomar(l => horas(l.ultima_actualizacion) * 60 > (num(l.sla_minutos) || 1440));
const altos       = tomar(l => String(l.nivel).toLowerCase() === 'alto');
const sinIntervencion = recientes.length - usados.size;

const vencido = (l) => horas(l.ultima_actualizacion) * 60 > (num(l.sla_minutos) || 1440);
const linea = (l) => {
  const p = num(l.presupuesto_uf) ? 'UF ' + num(l.presupuesto_uf).toLocaleString('es-CL')
          : (num(l.presupuesto_clp) ? '$' + num(l.presupuesto_clp).toLocaleString('es-CL') : 's/ presupuesto');
  return '· ' + (l.nombre || 'Sin nombre') + ' — ' + (l.comuna || 's/ comuna') + ' — ' + p +
         ' (score ' + (num(l.score) || 0) + ')' + (vencido(l) ? ' ⏰ SLA vencido' : '') +
         '\n  +' + l.telefono;
};

let m = '*Buenos días, Alice* ☀️\n_Tu resumen de hoy_\n\n';

if (!recientes.length) {
  m += 'No hay leads nuevos en las últimas 48 horas. Día tranquilo.';
} else {
  m += '📊 *' + recientes.length + ' leads* en las últimas 48 h\n\n';
  if (captaciones.length) {
    m += '🏡 *Captaciones* (' + captaciones.length + ') — esto es inventario, parte por acá\n' +
         captaciones.slice(0, 5).map(linea).join('\n') + '\n\n';
  }
  if (vencidos.length) {
    m += '🔴 *LLAMAR HOY — SLA vencido* (' + vencidos.length + ')\n' +
         vencidos.slice(0, 5).map(linea).join('\n') + '\n\n';
  }
  if (altos.length) {
    m += '⭐ *Alto valor* (' + altos.length + ')\n' +
         altos.slice(0, 5).map(linea).join('\n') + '\n\n';
  }
  if (!vencidos.length && !captaciones.length && !altos.length) {
    m += 'Nada urgente. El agente lo tiene todo cubierto.\n\n';
  }
  m += '✅ Agendados por el agente: *' + agendados.length + '*\n';
  m += '🤖 Sin necesidad de ti: *' + Math.max(0, sinIntervencion) + '*';
}

// ── Publicaciones por vencer: es trafico ya pagado que se pierde ──
const hoyISO = $now.toFormat('yyyy-MM-dd');
const diasHasta = (f) => {
  const t = Date.parse(String(f || '') + 'T12:00:00Z');
  if (isNaN(t)) return 9999;
  return Math.round((t - Date.parse(hoyISO + 'T12:00:00Z')) / 86400000);
};
const porVencer = props
  .filter(p => String(p.estado || '').toLowerCase().indexOf('disponible') === 0)
  .map(p => Object.assign({}, p, { dias: diasHasta(p.vence) }))
  .filter(p => p.dias >= 0 && p.dias <= 15)
  .sort((a, b) => a.dias - b.dias || num(b.visitas) - num(a.visitas));

if (porVencer.length) {
  m += '\n\n⏳ *Publicaciones por vencer* (' + porVencer.length + ')\n';
  m += porVencer.slice(0, 6).map(p => {
    const precio = num(p.uf) ? 'UF ' + num(p.uf).toLocaleString('es-CL')
                 : (num(p.clp) ? '$' + num(p.clp).toLocaleString('es-CL') : '');
    const urg = p.dias <= 7 ? '🔴' : '🟡';
    return urg + ' ' + p.dias + ' día' + (p.dias === 1 ? '' : 's') + ' — ' +
           (p.titulo || p.id) + '\n  ' + p.comuna + ' · ' + precio +
           ' · ' + num(p.visitas).toLocaleString('es-CL') + ' visitas acumuladas';
  }).join('\n');
  const top = porVencer[0];
  if (num(top.visitas) >= 100) {
    m += '\n\n_Ojo con la primera: son ' + num(top.visitas).toLocaleString('es-CL') +
         ' visitas de tráfico ya pagado que se pierden si no la renuevas._';
  }
}

return [{ json: { telefono_alice: $('Brief · CONFIG').first().json.telefono_alice, mensaje: m } }];

// GUARDA DE CONFIGURACION — falla RUIDOSAMENTE si el CONFIG quedo sin llenar.
//
// Por que existe: todos los nodos de WhatsApp tienen onError:continue, asi que
// un phone_number_id malo se ve VERDE en Executions y el mensaje nunca sale.
// Este nodo convierte ese fallo silencioso en una ejecucion roja y legible.
//
// Critico  -> tira error, corta la ejecucion.
// Opcional -> solo avisa, el bot sigue funcionando degradado.

const cfg = $json || {};
const vacio = (v) => {
  const s = String(v == null ? '' : v).trim();
  return !s || /^REEMPLAZAR/i.test(s);
};

const CRITICOS = [
  ['sheet_id', 'sin esto no se lee ninguna hoja y el agente responde sin stock'],
  ['whatsapp_phone_number_id', 'sin esto el bot NO puede responder — el mensaje muere en Graph'],
];
const OPCIONALES = [
  ['email_alice', 'no llegan las alertas de alto valor ni de tasacion'],
  ['telefono_alice', 'no llega el brief matinal'],
  ['calendar_id', 'no se crean los eventos de visita'],
];

const rotos = [];
for (const [k, porque] of CRITICOS) {
  if (vacio(cfg[k])) rotos.push(k + ' esta sin llenar — ' + porque);
}

// Chequeos de formato: atrapan el copy-paste a medias, que es peor que el vacio
// porque parece configurado.
const pid = String(cfg.whatsapp_phone_number_id || '').trim();
if (!vacio(pid) && !/^\d{10,20}$/.test(pid)) {
  rotos.push('whatsapp_phone_number_id debe ser solo digitos — llego: "' + pid + '"');
}
const sid = String(cfg.sheet_id || '').trim();
if (!vacio(sid) && !/^[A-Za-z0-9_-]{30,}$/.test(sid)) {
  rotos.push('sheet_id no parece un ID de Google Sheets — llego: "' + sid + '"');
}
const tel = String(cfg.telefono_alice || '').trim();
if (!vacio(tel) && !/^\d{9,15}$/.test(tel)) {
  rotos.push('telefono_alice debe ser solo digitos, sin + ni espacios — llego: "' + tel + '"');
}

if (rotos.length) {
  throw new Error(
    'CONFIG INCOMPLETO — el bot no va a poder responder.\n\n' +
    rotos.map(r => '  · ' + r).join('\n') +
    '\n\nArreglo: abre el nodo "⚙️ CONFIG · Cliente", completa esos campos, ' +
    'Save y Publish.\nOjo: re-importar el workflow los vuelve a dejar en REEMPLAZAR_*.'
  );
}

const avisos = OPCIONALES
  .filter(([k]) => vacio(cfg[k]))
  .map(([k, porque]) => k + ' — ' + porque);

// Pasa todo tal cual (el CONFIG trae includeOtherFields, o sea el body de Meta).
return [{ json: Object.assign({}, cfg, {
  _config_ok: true,
  _config_avisos: avisos,
  _config_resumen: avisos.length
    ? avisos.length + ' campo(s) opcional(es) sin llenar'
    : 'CONFIG completo'
}) }];

// GUARDA DE ENVIO — confirma que Meta acepto el mensaje.
//
// El nodo anterior tiene onError:continue, o sea que un 400 o un 401 pasan
// como si nada y la ejecucion queda verde. Aca se revisa la respuesta real:
// si Meta no devolvio un wamid, el contacto NO recibio nada y hay que verlo.

const r = $json || {};
const wamid = (r.messages && r.messages[0] && r.messages[0].id) || '';

if (wamid) {
  // El mensaje salio. Pero si la lectura de Sheets fallo, el agente contesto a
  // ciegas: sin memoria y sin stock. Eso NO puede verse verde en Executions.
  const prep = $('Contexto · Preparar').first().json;
  if (prep && prep.lectura_ok === false) {
    throw new Error(
      'LECTURA DE SHEETS CAIDA — el contacto recibio respuesta, pero a ciegas.\n\n' +
      '  El agente contesto sin stock y sin memoria: no recuerda la conversacion\n' +
      '  ni puede nombrar propiedades reales.\n\n' +
      '  Revisa los nodos "Stock · Leer propiedades" y "Estado · Leer conversación".\n' +
      '  Causa mas comun: la credencial de Google perdio la autorizacion.\n\n' +
      '  Se marca en rojo a proposito. Antes esto se veia verde y por eso paso\n' +
      '  desapercibido toda la tarde del 6 de agosto.'
    );
  }
  return [{ json: Object.assign({}, r, { _envio_ok: true, wamid_enviado: wamid,
                                         _lectura_ok: true }) }];
}

const err  = r.error || (r.body && r.body.error) || {};
const code = err.code != null ? err.code : (r.code != null ? r.code : '');
const sub  = err.error_subcode || '';
let msg    = err.message || r.message || '';
if (!msg) { try { msg = JSON.stringify(r).slice(0, 400); } catch (e) { msg = String(r); } }

const PISTAS = {
  190: 'token invalido o expirado → revisa la credencial "WhatsApp account 2" en n8n',
  200: 'al token le falta el permiso whatsapp_business_messaging',
  100: 'phone_number_id incorrecto, o la app no esta asignada al usuario del sistema',
  131030: 'ese numero no esta en la lista de destinatarios de prueba de Meta',
  131047: 'pasaron mas de 24 h desde el ultimo mensaje del contacto — hace falta una plantilla',
  131026: 'el numero destino no tiene WhatsApp o no puede recibir mensajes',
  368: 'la cuenta esta temporalmente bloqueada por politicas de Meta',
};

throw new Error(
  'WHATSAPP NO ENVIO EL MENSAJE' + (code !== '' ? ' (codigo ' + code + (sub ? '/' + sub : '') + ')' : '') + '\n\n' +
  '  ' + msg + '\n' +
  (PISTAS[code] ? '  → ' + PISTAS[code] + '\n' : '') +
  '\nEl contacto NO recibio nada. La ejecucion se marca en rojo a proposito: ' +
  'sin esta guarda se veria verde.'
);

// Reparte el brief entre todos los numeros de telefono_alice.
// WhatsApp acepta UN destinatario por llamada, asi que aca se emite un item por
// numero y el nodo HTTP corre una vez por cada uno.
const cfg = $('Brief · CONFIG').first().json;
const mensaje = $json.mensaje || '';

// Se corta SOLO por coma, punto y coma o salto de linea. Por espacios no:
// "+56 9 3219 1799" es un numero escrito como lo escribe cualquiera, no cuatro.
const numeros = String(cfg.telefono_alice || '')
  .split(/[,;\n]+/)
  .map(s => s.replace(/\D/g, ''))
  .filter(s => s.length >= 9 && s.length <= 15);

const unicos = [...new Set(numeros)];

// Sin destinatarios validos no se manda nada, pero se deja dicho por que.
if (!unicos.length) {
  return [{ json: {
    sin_destinatarios: true,
    motivo: 'telefono_alice vacio o mal escrito: "' + (cfg.telefono_alice || '') + '"',
    mensaje
  } }];
}

return unicos.map(t => ({ json: { telefono: t, mensaje, total: unicos.length } }));
